#!/bin/bash
# RTC — génération des tomes de fondation T1 à T4 : plan (Dialagram, sous contraintes), rédaction, nettoyage, PDF.
# Claude écrit seulement les consignes ci-dessous, puis relit chaque tome avant publication.
O=/home/user/agentsecctest1/bibliotheque/outils
D=/home/user/agentsecctest1/NCE/09_PUBLICATIONS
REGLES="RÈGLES ABSOLUES : (1) ne citer QUE les références de la liste ci-dessous, avec l'auteur et l'année indiqués ; n'en inventer aucune ; aucun DOI, aucun numéro de page, aucune citation entre guillemets attribuée à un chercheur ; (2) ne jamais présenter une intuition comme une preuve ; donner des preuves complètes pour les résultats démontrés dans le livre, et pour les grands théorèmes connus donner l'idée de la preuve en le disant ; (3) chaque affirmation porte un statut : PROUVÉ, CONNU, EXPÉRIMENTAL, CONJECTURE, RÉFUTÉ ou OUVERT ; (4) aucune annonce de découverte ; (5) formules en LaTeX entre \$...\$ ou \$\$...\$\$ ; (6) lecteur cultivé non spécialiste : intuition, définition, énoncé, exemple, exercice ; (7) dernier chapitre : « Transfert vers le programme RTC » (ce que ce tome apporte à l'étude des traductions à ressources : quelles ressources, quelles traductions, quelles questions ouvertes)."

livre() {  # $1 dossier, $2 titre, $3 sujet, $4 références
  mkdir -p $D/$1 && cd $D/$1
  cat > brief_plan.txt <<EOF
Tu es l'auteur, pour le compte d'Oussama Ghorbel, d'un livre de la collection scientifique « Les Traductions du Calcul » (programme de recherche RTC : étudier quelles ressources — taille, temps, mémoire, profondeur, largeur, précision, partage — chaque traduction entre modèles de calcul conserve ou perd). Titre : « $2 ». Sujet : $3

$REGLES

Références autorisées (et seulement elles) : $4

Conçois le plan d'un livre d'environ 220 pages : 4 parties, 16 chapitres (le 16e est le transfert vers RTC), 4 à 6 sections par chapitre, exercices. Réponds UNIQUEMENT avec un JSON valide, sans balises markdown :
{"titre":"$2","sous_titre":"...","these":"...","cadre":{"nom":"Les traductions à ressources et le registre des statuts","description":"(recopie ici intégralement les règles absolues ci-dessus et la liste des références autorisées)"},"bibliographie":[{"auteur":"...","titre":"...","annee":"...","idee":"...","apport":"..."}],"parties":[{"titre":"...","chapitres":[{"numero":1,"titre":"...","objectif":"...","sections":["..."],"exercices":["..."]}]}]}
EOF
  for i in 1 2 3; do
    [ -s plan.json ] && break
    python3 $O/ask.py brief_plan.txt plan_raw.txt
    python3 -c "
import json;t=open('plan_raw.txt').read().strip()
if t.startswith('\`\`\`'): t=t.split('\n',1)[1].rsplit('\`\`\`',1)[0]
p=json.loads(t);assert sum(len(x['chapitres']) for x in p['parties'])>=14
json.dump(p,open('plan.json','w'),ensure_ascii=False,indent=1)" 2>/dev/null || rm -f plan.json
  done
  [ -s plan.json ] || { echo "$1 ERREUR plan"; return; }
  python3 -u $O/redaction.py plan.json chapitres --parallele 4 > redaction.log 2>&1
  python3 -u $O/nettoyage.py chapitres chapitres_v2 > nettoyage.log 2>&1
  python3 $O/mise_en_page.py plan.json chapitres_v2 livre.pdf --corps 11.3 > pdf.log 2>&1
  echo "$1 FIN $(ls chapitres_v2/*.md 2>/dev/null | wc -l) fichiers ; $(tail -1 pdf.log)"
}
REGLES="$REGLES (8) livre RICHE EN FORMULES : chaque chapitre contient au moins 15 formules en LaTeX (display \$\$...\$\$), chacune accompagnée de son énoncé en mots, de ses conditions de validité, de son statut et d'un exemple numérique calculé pas à pas ; les démonstrations courtes sont écrites en entier."
livre T10 "Les Invariants du Calcul" "ce qui se conserve à travers toutes les traductions entre lambda-calcul, machines de Turing, circuits, SAT et réseaux de neurones : calculabilité, temps et taille à un polynôme près (thèse de Church-Turing étendue, statut à discuter), largeur arborescente et largeur de chemin comme invariants paramétrés (théorème de Courcelle, algorithmes en temps exponentiel en la largeur), profondeur et parallélisme (NC, TC0), précision, partage ; ressources robustes contre ressources fragiles ; barrières de preuve (relativisation, preuves naturelles, algébrisation) et ce qu'elles interdisent. Résultats du programme avec statut PROUVÉ : L-01 (Tseitin, largeur au plus (k+1)(w+1)-1), L-02 (tableau, largeur de chemin au plus 4s+1), L-03 (compilation à seuil, poids au plus 2) ; EXPÉRIMENTAL : E-01b (réseaux entraînés largeur 11 à 14 contre 1 à 3 compilés)." "Church 1936 (An unsolvable problem of elementary number theory) ; Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Cook 1971 (The complexity of theorem-proving procedures) ; Baker, Gill et Solovay 1975 (Relativizations of the P =? NP question) ; Pippenger et Fischer 1979 (Relations among complexity measures) ; Robertson et Seymour 1986 (Graph minors II: algorithmic aspects of tree-width) ; Courcelle 1990 (The monadic second-order logic of graphs I: recognizable sets of finite graphs) ; Siegelmann et Sontag 1995 (On the computational power of neural nets) ; Razborov et Rudich 1997 (Natural proofs) ; Aaronson et Wigderson 2009 (Algebrization: a new barrier in complexity theory) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach) ; Accattoli et Dal Lago 2016 ((Leftmost-outermost) beta reduction is invariant, indeed) ; Merrill et Sabharwal 2023 (The parallelism tradeoff: limitations of log-precision transformers)" &
livre Formulaire "Formulaire des Traductions du Calcul" "formulaire raisonné de la collection : toutes les formules utiles classées par domaine, chacune avec énoncé, conditions, statut, exemple chiffré et renvoi au domaine. Parties : (I) lambda-calcul (substitution, bêta-réduction, encodages de Church des entiers, booléens et paires, combinateur Y, types simples, coût de réduction) ; (II) machines de Turing et complexité (définitions des classes, hiérarchies de temps et d'espace, théorème de Savitch, simulation multi-ruban, Cook-Levin, simulation par circuits O(t log t)) ; (III) circuits, SAT et largeur (encodage de Tseitin clause par clause, transition de phase du 3-SAT aléatoire vers un ratio clauses/variables d'environ 4,27, borne de Schöning (4/3)^n, définitions de largeur arborescente et de chemin, lemmes L-01 et L-02) ; (IV) réseaux de neurones (neurone à seuil, portes ET OU XOR à seuil du lemme L-03, ReLU et sa relation avec le seuil sur entrées entières, approximation universelle, rétropropagation, attention softmax, comptage des régions linéaires d'un réseau ReLU) ; un dernier chapitre de tables de correspondance entre modèles avec coûts." "Church 1936 (An unsolvable problem of elementary number theory) ; Turing 1936 (On computable numbers, with an application to the Entscheidungsproblem) ; McCulloch et Pitts 1943 (A logical calculus of the ideas immanent in nervous activity) ; Hartmanis et Stearns 1965 (On the computational complexity of algorithms) ; Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Savitch 1970 (Relationships between nondeterministic and deterministic tape complexities) ; Cook 1971 (The complexity of theorem-proving procedures) ; Pippenger et Fischer 1979 (Relations among complexity measures) ; Barendregt 1984 (The Lambda Calculus: Its Syntax and Semantics) ; Rumelhart, Hinton et Williams 1986 (Learning representations by back-propagating errors) ; Cybenko 1989 (Approximation by superpositions of a sigmoidal function) ; Schöning 1999 (A probabilistic algorithm for k-SAT and constraint satisfaction problems) ; Arora et Barak 2009 (Computational Complexity: A Modern Approach) ; Telgarsky 2016 (Benefits of depth in neural networks) ; Vaswani et al. 2017 (Attention is all you need)" &
livre Information "Information et Calcul" "la théorie de l'information comme instrument d'étude des traductions entre modèles de calcul : entropie de Shannon, entropie conditionnelle, information mutuelle, inégalité de traitement des données, codage de source et de canal ; complexité de Kolmogorov, incompressibilité, invariance à une constante près selon la machine universelle (un invariant de traduction au sens fort), non-calculabilité ; complexité de communication de Yao, jeux de Karchmer-Wigderson et profondeur des formules ; coût énergétique du calcul (principe de Landauer, calcul réversible de Bennett) ; goulot d'information dans les réseaux de neurones (statut à discuter) ; économie de radix et coût de représentation selon la base (optimum en e, base 3 entière la plus proche). Distinguer clairement CONNU, CONJECTURE et OUVERT." "Shannon 1948 (A mathematical theory of communication) ; Landauer 1961 (Irreversibility and heat generation in the computing process) ; Solomonoff 1964 (A formal theory of inductive inference) ; Kolmogorov 1965 (Three approaches to the quantitative definition of information) ; Chaitin 1966 (On the length of programs for computing finite binary sequences) ; Bennett 1973 (Logical reversibility of computation) ; Yao 1979 (Some complexity questions related to distributive computing) ; Karchmer et Wigderson 1990 (Monotone circuits for connectivity require super-logarithmic depth) ; Cover et Thomas 1991 (Elements of Information Theory) ; Li et Vitányi 1993 (An Introduction to Kolmogorov Complexity and Its Applications) ; Kushilevitz et Nisan 1997 (Communication Complexity) ; Tishby, Pereira et Bialek 1999 (The information bottleneck method)" &
livre Crypto "Cryptographie et Complexité" "la cryptographie vue comme science des traductions qui doivent détruire l'information exploitable : secret parfait de Shannon et masque jetable, fonctions à sens unique et leur lien avec P différent de NP (l'existence de fonctions à sens unique implique P différent de NP, la réciproque est OUVERTE), générateurs pseudo-aléatoires à partir de toute fonction à sens unique, chiffrement probabiliste et sécurité sémantique, cryptographie à clé publique (Diffie-Hellman, RSA, fonctions à trappe), les cinq mondes d'Impagliazzo, cryptanalyse logique et algébrique (chiffrement traduit en circuit puis en CNF par Tseitin, solveurs SAT avec contraintes XOR), largeur structurelle des formules cryptographiques comme mesure de difficulté (hypothèse à marquer CONJECTURE), preuves naturelles comme obstacle lié à l'existence de générateurs pseudo-aléatoires." "Shannon 1949 (Communication theory of secrecy systems) ; Tseitin 1968 (On the complexity of derivation in propositional calculus) ; Diffie et Hellman 1976 (New directions in cryptography) ; Rivest, Shamir et Adleman 1978 (A method for obtaining digital signatures and public-key cryptosystems) ; Yao 1982 (Theory and applications of trapdoor functions) ; Goldwasser et Micali 1984 (Probabilistic encryption) ; Impagliazzo 1995 (A personal view of average-case complexity) ; Razborov et Rudich 1997 (Natural proofs) ; Håstad, Impagliazzo, Levin et Luby 1999 (A pseudorandom generator from any one-way function) ; Massacci et Marraro 2000 (Logical cryptanalysis as a SAT problem) ; Goldreich 2001 (Foundations of Cryptography: Basic Tools) ; Courtois et Pieprzyk 2002 (Cryptanalysis of block ciphers with overdefined systems of equations) ; Katz et Lindell 2007 (Introduction to Modern Cryptography) ; Soos, Nohl et Castelluccia 2009 (Extending SAT solvers to cryptographic problems)" &
wait
